import { readFile } from "node:fs/promises";
import { join } from "node:path";
import { ImageResponse } from "next/og";
import { profile } from "@/content/profile";

export const alt = `${profile.name} · ${profile.title}`;
export const size = { width: 1200, height: 630 };
export const contentType = "image/png";

/** Satori reads PNG/JPEG only, so the JPEG companion generated by `npm run images` is used here. */
async function headshotDataUrl(): Promise<string | null> {
  if (!profile.headshotOg) return null;
  try {
    const buf = await readFile(join(process.cwd(), "public", profile.headshotOg.replace(/^\//, "")));
    return `data:image/jpeg;base64,${buf.toString("base64")}`;
  } catch {
    return null;
  }
}

export default async function OpenGraphImage() {
  const headshot = await headshotDataUrl();

  return new ImageResponse(
    (
      <div
        style={{
          width: "100%",
          height: "100%",
          display: "flex",
          flexDirection: "column",
          justifyContent: "space-between",
          padding: 72,
          background:
            "radial-gradient(60% 60% at 15% 10%, rgba(34,211,238,0.28), transparent 60%), radial-gradient(50% 50% at 90% 90%, rgba(167,139,250,0.3), transparent 60%), #05060a",
          color: "#eceef4",
          fontFamily: "sans-serif",
        }}
      >
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
          <div style={{ display: "flex", alignItems: "center", gap: 14, fontSize: 24, color: "#8f94a6" }}>
            <div style={{ width: 12, height: 12, borderRadius: 999, background: "#22d3ee" }} />
            {profile.location.label}
          </div>
          {headshot && (
            // eslint-disable-next-line @next/next/no-img-element -- Satori renders plain <img>
            <img
              src={headshot}
              alt=""
              width={168}
              height={168}
              style={{
                width: 168,
                height: 168,
                borderRadius: 999,
                objectFit: "cover",
                border: "3px solid rgba(34,211,238,0.6)",
                boxShadow: "0 0 60px rgba(34,211,238,0.35)",
              }}
            />
          )}
        </div>
        <div style={{ display: "flex", flexDirection: "column", gap: 18 }}>
          <div style={{ fontSize: 112, fontWeight: 700, letterSpacing: -6, lineHeight: 1 }}>{profile.name}</div>
          <div style={{ fontSize: 40, color: "#22d3ee", fontWeight: 500 }}>{profile.title}</div>
          <div style={{ fontSize: 28, color: "#8f94a6", maxWidth: 900, lineHeight: 1.35 }}>{profile.tagline}</div>
        </div>
        <div style={{ display: "flex", gap: 28, fontSize: 22, color: "#8f94a6" }}>
          {["React", "Next.js", "TypeScript", "Go", "Node.js", "PostgreSQL", "AWS", "AI"].map((t) => (
            <span key={t}>{t}</span>
          ))}
        </div>
      </div>
    ),
    size,
  );
}
